/* ── OG Demos logic ── */
function openOGDemo(src, label, hint){
  document.getElementById('og-modal-label').textContent = label;
  document.getElementById('og-modal-title').textContent = label;
  document.getElementById('og-modal-hint').textContent = hint;
  const iframe = document.getElementById('og-modal-iframe');
  if(src){ iframe.src = src; iframe.style.display='block'; }
  else { iframe.style.display='none'; }
  document.getElementById('og-modal-overlay').style.display='block';
  const wrap = document.getElementById('og-modal-wrap');
  wrap.style.display='flex';
}
function closeOGModal(){
  document.getElementById('og-modal-overlay').style.display='none';
  const wrap = document.getElementById('og-modal-wrap');
  wrap.style.display='none';
  document.getElementById('og-modal-iframe').src='about:blank';
}

