function etUI(k){ const lg=(typeof curLg==='function')?curLg():((window.H3LSite&&H3LSite.lang&&H3LSite.lang())||'es'); const u=ET_UI[lg]||ET_UI.es; return u[k]; }
function etApp(a){ const lg=(window.H3LSite&&H3LSite.lang&&H3LSite.lang())||'es'; if(lg==='es'||!ET_TR[lg]||!ET_TR[lg][a.id]) return a; const t=ET_TR[lg][a.id];
  return Object.assign({},a,{title:t[0],query:t[1],desc:t[2],metric:t[3],val:t[4],vany:t[5],calcConclusion:d=>t[6].replace('{d}',d)}); }
function etLabel(l){ const lg=(window.H3LSite&&H3LSite.lang&&H3LSite.lang())||'es'; if(lg==='es') return l; const m=ET_LAB[lg]||{}; const mt=/^T(\d)-(\d\d)$/.exec(l); if(mt) return (lg==='en'?'Q':'T')+mt[1]+'-'+mt[2];
  const p=String(l).split(' '); if(m[p[0]]!==undefined){ p[0]=m[p[0]]; return p.join(' '); } return l; }
function etApplyStatic(){ document.querySelectorAll('[data-et]').forEach(e=>{ const v=etUI(e.getAttribute('data-et')); if(v!==undefined) e.textContent=v; }); }
function buildETGrid(){
  const grid = document.getElementById('et-grid');
  if(!grid) return;
  etApplyStatic();
  grid.innerHTML = ET_APPS.map(etApp).map(a=>{
    const badgeCls = a.status==='crit'?'et-badge-crit':a.status==='warn'?'et-badge-warn':'et-badge-ok';
    const badgeLabel = a.status==='crit'?etUI('badge_crit'):a.status==='warn'?etUI('badge_warn'):etUI('badge_ok');
    return `<div class="et-card">
      <span class="et-badge ${badgeCls}">${badgeLabel}</span>
      <div class="et-card-meta">${a.id}</div>
      <div class="et-card-title">${a.title}</div>
      <div class="et-card-desc">${a.desc}</div>
      <div class="et-card-footer">
        <span class="et-card-metric">${a.metric} · ${a.val}</span>
        <button class="et-btn-demo" onclick="openETModal('${a.id}')">${etUI('audit')}</button>
      </div>
    </div>`;
  }).join('');
}

function openETModal(id){
  const app0 = ET_APPS.find(a=>a.id===id);
  if(!app0) return;
  const app = etApp(app0);
  _etOpenId = id; etApplyStatic();
  document.getElementById('et-m-tag').textContent = app.id;
  document.getElementById('et-m-title').textContent = app.title;
  document.getElementById('et-m-query').textContent = app.query;

  // Random real data
  const realData = app.base.map(v => +(v * (1 + (Math.random()-.5)*.12)).toFixed(2));
  const lastIdx = app.base.length - 1;
  const dev = Math.abs(((realData[lastIdx]-app.base[lastIdx])/app.base[lastIdx])*100).toFixed(1);

  document.getElementById('et-m-meta').innerHTML = `
    <div><div style="font-size:10px;color:#9ca3af;font-weight:600;text-transform:uppercase;">${etUI('m')}</div><div style="font-weight:700;font-family:monospace;margin-top:2px;">${app.metric}</div></div>
    <div><div style="font-size:10px;color:#9ca3af;font-weight:600;text-transform:uppercase;">${etUI('r')}</div><div style="font-weight:700;font-family:monospace;margin-top:2px;">${app.val}</div></div>
    <div><div style="font-size:10px;color:#9ca3af;font-weight:600;text-transform:uppercase;">${etUI('e')}</div><div style="font-weight:700;margin-top:2px;color:${app.status==='ok'?'#047857':app.status==='warn'?'#b45309':'#b91c1c'}">${app.status.toUpperCase()}</div></div>
    <div><div style="font-size:10px;color:#9ca3af;font-weight:600;text-transform:uppercase;">${etUI('dv')}</div><div style="font-weight:700;font-family:monospace;margin-top:2px;">${dev}%</div></div>`;

  document.getElementById('et-m-conclusion').innerHTML = app.calcConclusion(dev);

  document.getElementById('et-modal-overlay').style.display='block';
  document.getElementById('et-modal-wrap').style.display='block';

  if(_etChart) _etChart.destroy();
  const ctx = document.getElementById('et-modal-chart').getContext('2d');
  _etChart = new Chart(ctx,{
    type:'line',
    data:{
      labels: app.labels.map(etLabel),
      datasets:[
        {label:etUI('base'),data:app.base,borderColor:'#2357a5',borderDash:[5,3],backgroundColor:'transparent',pointRadius:0,borderWidth:1.5},
        {label:etUI('real'),data:realData,borderColor:app.status==='crit'?'#b91c1c':app.status==='warn'?'#b45309':'#047857',backgroundColor:app.status==='crit'?'rgba(185,28,28,.08)':app.status==='warn'?'rgba(180,83,9,.08)':'rgba(4,120,87,.08)',fill:true,pointRadius:3,borderWidth:2}
      ]
    },
    options:{responsive:true,plugins:{legend:{position:'top',labels:{font:{size:11}}}},scales:{y:{title:{display:true,text:app.vany,font:{size:10}},grid:{color:'#f3f4f6'}},x:{grid:{color:'#f3f4f6'}}}}
  });
}

function closeETModal(){
  document.getElementById('et-modal-overlay').style.display='none';
  document.getElementById('et-modal-wrap').style.display='none';
  if(_etChart){ _etChart.destroy(); _etChart=null; }
}

// Build ET grid on load
document.addEventListener('DOMContentLoaded', function(){
  buildETGrid();
});

// Lazy load Chart.js if not present
(function(){
  if(!window.Chart){
    const s=document.createElement('script');
    s.src='assets/vendor/chart.umd.min.js';
    s.onload=function(){ buildETGrid(); };
    document.head.appendChild(s);
  }
})();
